con=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
views={n:s for (n,s) in con.execute("select name,sql from sqlite_master where type='view'")}
def objs(sql):
    return set(re.findall(r'(?:FROM|JOIN)\s+"?([A-Za-z_][A-Za-z0-9_]*)"?', sql, re.I))
def expand(name, seen=None):
    seen = seen or set()
    out=set()
    for o in objs(views[name]):
        if o in views and o not in seen:
            out |= expand(o, seen|{name})
        elif o not in views:
            out.add(o)
    return out
for v in ['v_item_provenance','v_source_reach_all','v_determination_provenance','v_divergence','v_pending']:
    base=expand(v)
    stages={}
    for t in sorted(base): stages.setdefault(S.get(t,'UNMAPPED'),[]).append(t)
    non_base=[s for s in stages if s not in ('base',)]
    print(f"{v:32} stages={sorted(stages)}  cross={'YES' if len(non_base)>1 else 'no'}")
